import 'package:flutter/material.dart';
import '../app.dart';
import '../state/app_state.dart';
class HomeScreen extends StatelessWidget { const HomeScreen({super.key}); @override Widget build(BuildContext context){ final state=AppScope.of(context); final trainer=state.role==AppRole.trainer; final modules=trainer?_trainerModules:_memberModules; return Scaffold(appBar: AppBar(title: Text(trainer?'Trainer App':'Member App')), body: ListView(padding: const EdgeInsets.all(16), children:[ Text(trainer?'Coach clients and manage bookings':'Track workouts, attendance, nutrition, and purchases', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height:16), for(final m in modules) Card(child: ListTile(leading: Icon(m.$3), title: Text(m.$1), subtitle: Text(m.$2), trailing: const Icon(Icons.chevron_right), onTap:()=>Navigator.pushNamed(context,'/module',arguments:m.$1))) ])); }}
const _memberModules=[('QR Attendance','Scan branch QR codes and view visits',Icons.qr_code),('Memberships','Renew plans and view invoices',Icons.card_membership),('Workouts','Assigned workout programs',Icons.fitness_center),('Nutrition','Meal plans and macros',Icons.restaurant),('Store','Buy products and supplements',Icons.store),('Payments','Razorpay checkout history',Icons.payment),('WhatsApp','Renewal and booking alerts',Icons.chat)];
const _trainerModules=[('Trainer Bookings','Manage PT sessions',Icons.calendar_month),('Client Workouts','Assign programs',Icons.fitness_center),('Client Nutrition','Review meal plans',Icons.restaurant),('Progress','Track member outcomes',Icons.show_chart),('WhatsApp','Send coaching reminders',Icons.chat)];
